def dig(obj, *path):
    cur = obj
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return MISSING
        cur = cur[key]
    return cur

print('dig user.profile.email :', dig(data, 'user', 'profile', 'email'))
print('dig user.profile.backup:', dig(data, 'user', 'profile', 'backup'))
