import json

text = '{"price": 10, "price": 12, "qty": 3}'
print('plain loads:', json.loads(text))

def no_dupes(pairs):
    obj = {}
    for k, v in pairs:
        if k in obj:
            raise ValueError(f'duplicate key: {k}')
        obj[k] = v
    return obj

try:
    json.loads(text, object_pairs_hook=no_dupes)
except ValueError as e:
    print('strict hook raised ValueError:', e)

