import json

lines = [
    '{"id": 1, "total": 10}',
    '{"id": 2, "total": 20}',
    '{"id": 3, "total": }',
    '{"id": 4, "total": 40}',
]

def load_strict(lines):
    records = []
    for lineno, line in enumerate(lines, start=1):
        try:
            records.append(json.loads(line))
        except json.JSONDecodeError as e:
            raise ValueError(f'line {lineno}: invalid JSON ({e.msg})') from e
    return records

try:
    load_strict(lines)
except ValueError as e:
    print('loader stopped:', e)

def sniff(text):
    stripped = text.lstrip('\ufeff \t\r\n')
    if stripped.startswith('{') or stripped.startswith('['):
        return 'json'
    first_line = stripped.splitlines()[0] if stripped else ''
    if ';' in first_line:
        return 'csv (semicolon)'
    if ',' in first_line:
        return 'csv (comma)'
    return 'unknown'

files = {
    'data.csv': '{"id": 1, "total": 10}',
    'data.json': 'id,total\n1,10\n',
    'export.txt': 'id;total\n1;10\n',
}
for name, content in files.items():
    print(f'{name:12} content says: {sniff(content)}')

